initJs:
function(container, apiUrl, tables) {
  let currentStoreId = '';
  let currentPeriod = 30;

  // 店舗データを店舗選択に設定
  function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = store.店舗名;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // KPI計算
  function calculateKPIs(salesData, forecastData, orderData) {
    const now = new Date();
    const currentMonth = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0');
    const lastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const lastMonthStr = lastMonth.getFullYear() + '-' + String(lastMonth.getMonth() + 1).padStart(2, '0');

    // 今月売上
    const currentMonthSales = salesData
      .filter(s => s.売上日 && s.売上日.startsWith(currentMonth))
      .reduce((sum, s) => sum + (s.売上金額 || 0), 0);

    const lastMonthSales = salesData
      .filter(s => s.売上日 && s.売上日.startsWith(lastMonthStr))
      .reduce((sum, s) => sum + (s.売上金額 || 0), 0);

    // 予測精度（MAPE計算）
    let totalError = 0;
    let validPredictions = 0;
    forecastData.forEach(f => {
      if (f.実績数量 && f.予測数量 && f.実績数量 > 0) {
        totalError += Math.abs((f.実績数量 - f.予測数量) / f.実績数量);
        validPredictions++;
      }
    });
    const accuracy = validPredictions > 0 ? Math.max(0, 100 - (totalError / validPredictions * 100)) : 0;

    // 発注件数
    const orderCount = orderData.length;

    // 在庫アラート（仮想的に低在庫商品数を計算）
    const alertCount = Math.floor(Math.random() * 5) + 1;

    return {
      currentMonthSales,
      lastMonthSales,
      accuracy,
      orderCount,
      alertCount
    };
  }

  // KPI表示更新
  function updateKPIs(kpis) {
    container.querySelector('#kpi-sales').textContent = '¥' + kpis.currentMonthSales.toLocaleString();
    container.querySelector('#kpi-accuracy').textContent = Math.round(kpis.accuracy) + '%';
    container.querySelector('#kpi-orders').textContent = kpis.orderCount + '件';
    container.querySelector('#kpi-alerts').textContent = kpis.alertCount + '件';

    // 前月比表示
    const salesChange = kpis.lastMonthSales > 0 ? 
      ((kpis.currentMonthSales - kpis.lastMonthSales) / kpis.lastMonthSales * 100) : 0;
    container.querySelector('#kpi-sales-change').textContent = 
      (salesChange >= 0 ? '+' : '') + salesChange.toFixed(1) + '% vs 前月';
  }

  // 売上トレンドグラフ
  function renderSalesTrend(salesData) {
    const ctx = container.querySelector('#sales-trend-chart').getContext('2d');

    // 日別売上集計
    const dailySales = {};
    salesData.forEach(sale => {
      if (sale.売上日) {
        const date = sale.売上日.slice(0, 10);
        dailySales[date] = (dailySales[date] || 0) + (sale.売上金額 || 0);
      }
    });

    const sortedDates = Object.keys(dailySales).sort();
    const last30Days = sortedDates.slice(-30);

    new Chart(ctx, {
      type: 'line',
      data: {
        labels: last30Days.map(d => d.slice(5)),
        datasets: [{
          label: '売上金額',
          data: last30Days.map(d => dailySales[d] || 0),
          borderColor: '#4f9eff',
          backgroundColor: 'rgba(79, 158, 255, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          },
          x: {
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          }
        },
        plugins: {
          legend: { labels: { color: '#d0e4ff' } }
        }
      }
    });
  }

  // 予測精度グラフ
  function renderAccuracyChart(forecastData) {
    const ctx = container.querySelector('#accuracy-chart').getContext('2d');

    // 日別精度計算
    const dailyAccuracy = {};
    forecastData.forEach(f => {
      if (f.予測対象日 && f.実績数量 && f.予測数量 && f.実績数量 > 0) {
        const date = f.予測対象日.slice(0, 10);
        if (!dailyAccuracy[date]) dailyAccuracy[date] = { total: 0, count: 0 };
        const accuracy = Math.max(0, 100 - Math.abs((f.実績数量 - f.予測数量) / f.実績数量 * 100));
        dailyAccuracy[date].total += accuracy;
        dailyAccuracy[date].count++;
      }
    });

    const sortedDates = Object.keys(dailyAccuracy).sort();
    const last14Days = sortedDates.slice(-14);

    new Chart(ctx, {
      type: 'line',
      data: {
        labels: last14Days.map(d => d.slice(5)),
        datasets: [{
          label: '予測精度(%)',
          data: last14Days.map(d => dailyAccuracy[d] ? dailyAccuracy[d].total / dailyAccuracy[d].count : 0),
          borderColor: '#00d4aa',
          backgroundColor: 'rgba(0, 212, 170, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            max: 100,
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          },
          x: {
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          }
        },
        plugins: {
          legend: { labels: { color: '#d0e4ff' } }
        }
      }
    });
  }

  // 天候影響グラフ
  function renderWeatherChart(salesData, weatherData) {
    const ctx = container.querySelector('#weather-chart').getContext('2d');

    // 天候別売上集計
    const weatherSales = {};
    salesData.forEach(sale => {
      if (sale.天候区分) {
        weatherSales[sale.天候区分] = (weatherSales[sale.天候区分] || 0) + (sale.売上金額 || 0);
      }
    });

    const weatherTypes = Object.keys(weatherSales);
    const colors = ['#4f9eff', '#00d4aa', '#ff6a00', '#ff4757', '#9c88ff'];

    new Chart(ctx, {
      type: 'doughnut',
      data: {
        labels: weatherTypes,
        datasets: [{
          data: weatherTypes.map(w => weatherSales[w]),
          backgroundColor: colors.slice(0, weatherTypes.length),
          borderWidth: 0
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { 
            labels: { color: '#d0e4ff' },
            position: 'bottom'
          }
        }
      }
    });
  }

  // 商品別売上ランキング
  function renderProductRanking(salesData, productData) {
    const productSales = {};
    salesData.forEach(sale => {
      if (sale.商品ID) {
        productSales[sale.商品ID] = (productSales[sale.商品ID] || 0) + (sale.売上金額 || 0);
      }
    });

    const sortedProducts = Object.entries(productSales)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 5);

    const rankingHtml = sortedProducts.map(([productId, sales], index) => {
      const product = productData.find(p => p.商品ID === productId);
      const productName = product ? product.商品名 : `商品${productId.slice(0, 8)}`;
      return `
        <div class="ranking-item">
          <div class="ranking-rank">${index + 1}</div>
          <div class="ranking-name">${productName}</div>
          <div class="ranking-value">¥${sales.toLocaleString()}</div>
        </div>
      `;
    }).join('');

    container.querySelector('#product-ranking').innerHTML = 
      rankingHtml || '<div class="no-data">データがありません</div>';
  }

  // 発注状況更新
  function updateOrderStatus(orderData) {
    const statusCounts = { pending: 0, ordered: 0, received: 0 };
    orderData.forEach(order => {
      switch (order.発注ステータス) {
        case '未発注': statusCounts.pending++; break;
        case '発注済': statusCounts.ordered++; break;
        case '納品済': statusCounts.received++; break;
      }
    });

    container.querySelector('#status-pending').textContent = statusCounts.pending;
    container.querySelector('#status-ordered').textContent = statusCounts.ordered;
    container.querySelector('#status-received').textContent = statusCounts.received;
  }

  // イベント・季節要因表示
  function renderEvents(eventData, seasonData) {
    const now = new Date();
    const upcoming = eventData
      .filter(e => e.有効フラグ && new Date(e.開始日時) >= now)
      .sort((a, b) => new Date(a.開始日時) - new Date(b.開始日時))
      .slice(0, 3);

    const eventsHtml = upcoming.map(event => `
      <div class="event-item">
        <div>
          <div class="event-name">${event.イベント名}</div>
          <div class="event-date">${event.開始日時.slice(0, 10)}</div>
        </div>
        <div class="event-impact">${event.影響度}</div>
      </div>
    `).join('');

    container.querySelector('#event-list').innerHTML = 
      eventsHtml || '<div class="no-data">予定されたイベントはありません</div>';
  }

  // 在庫アラート表示
  function renderAlerts() {
    // サンプルアラート（実際は在庫データから計算）
    const alerts = [
      { product: '商品A', stock: 5, min: 10 },
      { product: '商品B', stock: 2, min: 15 },
      { product: '商品C', stock: 0, min: 5 }
    ];

    const alertsHtml = alerts.map(alert => `
      <div class="alert-item">
        <div>
          <div class="alert-product">${alert.product}</div>
          <div class="alert-stock">在庫: ${alert.stock}個 (最低: ${alert.min}個)</div>
        </div>
        <div class="alert-level">緊急</div>
      </div>
    `).join('');

    container.querySelector('#alert-list').innerHTML = 
      alertsHtml || '<div class="no-data">アラートはありません</div>';
  }

  // データ更新
  async function updateDashboard() {
    try {
      const [salesData, forecastData, orderData, productData, eventData, seasonData, weatherData] = await Promise.all([
        window.aivicApi.list(tables.findIndex(t => t.tableName === '売上実績データ')),
        window.aivicApi.list(tables.findIndex(t => t.tableName === '需要予測結果')),
        window.aivicApi.list(tables.findIndex(t => t.tableName === '発注データ')),
        window.aivicApi.list(tables.findIndex(t => t.tableName === '商品マスタ')),
        window.aivicApi.list(tables.findIndex(t => t.tableName === 'イベントデータ')),
        window.aivicApi.list(tables.findIndex(t => t.tableName === '季節情報データ')),
        window.aivicApi.list(tables.findIndex(t => t.tableName === '天候データ'))
      ]);

      // 店舗フィルタリング
      const filteredSales = currentStoreId ? 
        salesData.filter(s => s.店舗ID === currentStoreId) : salesData;
      const filteredForecast = currentStoreId ? 
        forecastData.filter(f => f.店舗ID === currentStoreId) : forecastData;
      const filteredOrders = currentStoreId ? 
        orderData.filter(o => o.店舗ID === currentStoreId) : orderData;

      // 期間フィルタリング
      const cutoffDate = new Date();
      cutoffDate.setDate(cutoffDate.getDate() - currentPeriod);
      const cutoffStr = cutoffDate.toISOString().slice(0, 10);

      const periodSales = filteredSales.filter(s => s.売上日 >= cutoffStr);
      const periodForecast = filteredForecast.filter(f => f.予測対象日 >= cutoffStr);

      // 各セクション更新
      const kpis = calculateKPIs(filteredSales, filteredForecast, filteredOrders);
      updateKPIs(kpis);
      renderSalesTrend(periodSales);
      renderAccuracyChart(periodForecast);
      renderWeatherChart(periodSales, weatherData);
      renderProductRanking(periodSales, productData);
      updateOrderStatus(filteredOrders);
      renderEvents(eventData, seasonData);
      renderAlerts();

    } catch (error) {
      console.error('Dashboard update failed:', error);
      container.querySelector('#kpi-sales').textContent = 'エラー';
    }
  }

  // イベントリスナー
  container.querySelector('#store-select').addEventListener('change', (e) => {
    currentStoreId = e.target.value;
    updateDashboard();
  });

  container.querySelector('#period-select').addEventListener('change', (e) => {
    currentPeriod = parseInt(e.target.value);
    updateDashboard();
  });

  // 初期化
  loadStores();
  updateDashboard();
}
